    {
      "ids": ["EFF-01", "EFF-02"],
      "type": "resource",
      "description": "Efficiency measures may lead to increased energy consumption, conflicting with GRN-01 and GRN-06."
    },
    {
      "ids": ["SAF-02", "EFF-05"],
      "type": "resource",
      "description": "Balancing automatic withdrawals with energy efficiency must ensure that sustainability is not compromised."
    }
  ],
  "positions": [
